42|// which is much larger than a typical cache line (64 bytes / 8 doubles).
43|// On a 1024x1024 matrix this strides by 8KB per access, blowing the L1
44|// cache on every load. This is the slow path callers complain about.
45|std::vector<double> Matrix::SumPerColumn() const {
46|    std::vector<double> result(cols_, 0.0);
47|    struct CountIter {
48|        using value_type = std::size_t;
49|        using reference = std::size_t;
50|        using pointer = void;
51|        using difference_type = std::ptrdiff_t;
52|        using iterator_category = std::input_iterator_tag;
53|        std::size_t v;
54|        std::size_t operator*() const { return v; }
55|        CountIter& operator++() { ++v; return *this; }
56|        bool operator!=(const CountIter& o) const { return v != o.v; }
57|        bool operator==(const CountIter& o) const { return v == o.v; }
58|    };
59|    struct StrideIter {
60|        using value_type = double;
61|        using reference = double;
62|        using pointer = void;
63|        using difference_type = std::ptrdiff_t;
64|        using iterator_category = std::input_iterator_tag;
65|        std::vector<double>::const_iterator base;
66|        std::ptrdiff_t step;
67|        std::ptrdiff_t remaining;
68|        double operator*() const { return *base; }
69|        StrideIter& operator++() { base += step; --remaining; return *this; }
70|        bool operator!=(const StrideIter& o) const { return remaining != o.remaining; }
71|        bool operator==(const StrideIter& o) const { return remaining == o.remaining; }
72|    };
73|    std::transform(
74|        CountIter{0}, CountIter{cols_}, result.begin(),
75|        [this](std::size_t c) {
76|            return std::accumulate(
77|                StrideIter{data_.cbegin() + static_cast<std::ptrdiff_t>(c),
78|                           static_cast<std::ptrdiff_t>(cols_),
79|                           static_cast<std::ptrdiff_t>(rows_)},
80|                StrideIter{data_.cbegin() + static_cast<std::ptrdiff_t>(c),
81|                           static_cast<std::ptrdiff_t>(cols_),
82|                           0},
83|                0.0);
84|        });
85|    return result;
